// Where the map gets its data. Edit this file, or open the page with ?sheet=<id> to point at a
// Google Sheet without editing anything.
//
// source "mock"    reads the CSV tabs in data/mock/ (generated by build/mockdata.py)
// source "google"  the viewer signs in with their Google account and the page reads the sheet with
//                  the viewer's own access (Sheets API). Works for sheets shared only inside the
//                  Workspace domain. Needs clientId: an OAuth web client id from Google Cloud with
//                  the page's origin (http://localhost:8766) listed as an authorized JavaScript origin.
// source "sheet"   reads a sheet shared as "Anyone with the link can view" through Google's CSV
//                  export. No sign-in, but the sheet has to be public by link.
export const config = {
  source: 'google',
  sheetId: '1tT_SChzpdqtbm1lqHkBSnXwP96ffZzcHei8698v1P5I',   // DBS Buyer Zips
  clientId: '952835319425-0rigljq2rb5eiuo3omce67co7qh7m7no.apps.googleusercontent.com',
  mockDir: '../data/mock/',
  geoDir: '../data/geo/',
};
